// Generated by scripts/fetch_verses.py — 和合本 (CUV, public domain) + World English Bible (public domain)
window.BIBLE_TEXT = window.BIBLE_TEXT || {};
window.BIBLE_TEXT["ruth"] = {
 "1": {
  "1": {
   "zh": "當士師秉政的時候，國中遭遇饑荒。在猶大的伯利恆，有一個人帶著妻子和兩個兒子往摩押地去寄居。",
   "en": "In the days when the judges judged, there was a famine in the land. A certain man of Bethlehem Judah went to live in the country of Moab, he, and his wife, and his two sons."
  },
  "2": {
   "zh": "這人名叫以利米勒，他的妻名叫拿俄米；他兩個兒子，一個名叫瑪倫，一個名叫基連，都是猶大伯利恆的以法他人。他們到了摩押地，就住在那裡。",
   "en": "The name of the man was Elimelech, and the name of his wife Naomi. The names of his two sons were Mahlon and Chilion, Ephrathites of Bethlehem Judah. They came into the country of Moab, and lived there."
  },
  "3": {
   "zh": "後來拿俄米的丈夫以利米勒死了，剩下婦人和她兩個兒子。",
   "en": "Elimelech, Naomi’s husband, died; and she was left with her two sons."
  },
  "4": {
   "zh": "這兩個兒子娶了摩押女子為妻，一個名叫俄珥巴，一個名叫路得，在那裡住了約有十年。",
   "en": "They took for themselves wives of the women of Moab. The name of the one was Orpah, and the name of the other was Ruth. They lived there about ten years."
  },
  "5": {
   "zh": "瑪倫和基連二人也死了，剩下拿俄米，沒有丈夫，也沒有兒子。",
   "en": "Mahlon and Chilion both died, and the woman was bereaved of her two children and of her husband."
  },
  "6": {
   "zh": "她就與兩個兒婦起身，要從摩押地歸回；因為她在摩押地聽見耶和華眷顧自己的百姓，賜糧食與他們。",
   "en": "Then she arose with her daughters-in-law, that she might return from the country of Moab; for she had heard in the country of Moab how Yahweh had visited his people in giving them bread."
  },
  "7": {
   "zh": "於是她和兩個兒婦起行離開所住的地方，要回猶大地去。",
   "en": "She went out of the place where she was, and her two daughters-in-law with her. They went on the way to return to the land of Judah."
  },
  "8": {
   "zh": "拿俄米對兩個兒婦說：「你們各人回娘家去吧。願耶和華恩待你們，像你們恩待已死的人與我一樣！",
   "en": "Naomi said to her two daughters-in-law, “Go, return each of you to her mother’s house. May Yahweh deal kindly with you, as you have dealt with the dead, and with me."
  },
  "9": {
   "zh": "願耶和華使你們各在新夫家中得平安！」於是拿俄米與她們親嘴。她們就放聲而哭，",
   "en": "May Yahweh grant you that you may find rest, each of you in the house of her husband.” Then she kissed them, and they lifted up their voices, and wept."
  },
  "10": {
   "zh": "說：「不然，我們必與你一同回你本國去。」",
   "en": "They said to her, “No, but we will return with you to your people.”"
  },
  "11": {
   "zh": "拿俄米說：「我女兒們哪，回去吧！為何要跟我去呢？我還能生子作你們的丈夫嗎？",
   "en": "Naomi said, “Go back, my daughters. Why do you want to go with me? Do I still have sons in my womb, that they may be your husbands?"
  },
  "12": {
   "zh": "我女兒們哪，回去吧！我年紀老邁，不能再有丈夫；即或說，我還有指望，今夜有丈夫可以生子，",
   "en": "Go back, my daughters, go your way; for I am too old to have a husband. If I should say, ‘I have hope,’ if I should even have a husband tonight, and should also bear sons;"
  },
  "13": {
   "zh": "你們豈能等著他們長大呢？你們豈能等著他們不嫁別人呢？我女兒們哪，不要這樣。我為你們的緣故甚是愁苦，因為耶和華伸手攻擊我。」",
   "en": "would you then wait until they were grown? Would you then refrain from having husbands? No, my daughters, for it grieves me seriously for your sakes, for Yahweh’s hand has gone out against me.”"
  },
  "14": {
   "zh": "兩個兒婦又放聲而哭，俄珥巴與婆婆親嘴而別，只是路得捨不得拿俄米。",
   "en": "They lifted up their voices, and wept again; then Orpah kissed her mother-in-law, but Ruth joined with her."
  },
  "15": {
   "zh": "拿俄米說：「看哪，你嫂子已經回她本國和她所拜的神那裡去了，你也跟著你嫂子回去吧！」",
   "en": "She said, “Behold, your sister-in-law has gone back to her people, and to her god. Follow your sister-in-law.”"
  },
  "16": {
   "zh": "路得說：「不要催我回去不跟隨你。你往哪裡去，我也往那裡去；你在哪裡住宿，我也在那裡住宿；你的國就是我的國，你的神就是我的神。",
   "en": "Ruth said, “Don’t urge me to leave you, and to return from following you, for where you go, I will go; and where you stay, I will stay. Your people will be my people, and your God my God."
  },
  "17": {
   "zh": "你在哪裡死，我也在那裡死，也葬在那裡。除非死能使你我相離！不然，願耶和華重重地降罰與我。」",
   "en": "Where you die, I will die, and there I will be buried. May Yahweh do so to me, and more also, if anything but death parts you and me.”"
  },
  "18": {
   "zh": "拿俄米見路得定意要跟隨自己去，就不再勸她了。",
   "en": "When she saw that she was determined to go with her, she stopped urging her."
  },
  "19": {
   "zh": "於是二人同行，來到伯利恆。她們到了伯利恆，合城的人就都驚訝。婦女們說：「這是拿俄米嗎？」",
   "en": "So they both went until they came to Bethlehem. When they had come to Bethlehem, all the city was excited about them, and they asked, “Is this Naomi?”"
  },
  "20": {
   "zh": "拿俄米對他們說：「不要叫我拿俄米（就是甜的意思），要叫我瑪拉（就是苦的意思），因為全能者使我受了大苦。",
   "en": "She said to them, “Don’t call me Naomi. Call me Mara; for the Almighty has dealt very bitterly with me."
  },
  "21": {
   "zh": "我滿滿地出去，耶和華使我空空地回來。耶和華降禍與我；全能者使我受苦。既是這樣，你們為何還叫我拿俄米呢？」",
   "en": "I went out full, and Yahweh has brought me home again empty. Why do you call me Naomi, since Yahweh has testified against me, and the Almighty has afflicted me?”"
  },
  "22": {
   "zh": "拿俄米和她兒婦摩押女子路得，從摩押地回來到伯利恆，正是動手割大麥的時候。",
   "en": "So Naomi returned, and Ruth the Moabitess, her daughter-in-law, with her, who returned out of the country of Moab. They came to Bethlehem in the beginning of barley harvest."
  }
 },
 "2": {
  "1": {
   "zh": "拿俄米的丈夫以利米勒的親族中，有一個人名叫波阿斯，是個大財主。",
   "en": "Naomi had a relative of her husband’s, a mighty man of wealth, of the family of Elimelech, and his name was Boaz."
  },
  "2": {
   "zh": "摩押女子路得對拿俄米說：「容我往田間去，我蒙誰的恩，就在誰的身後拾取麥穗。」拿俄米說：「女兒啊，你只管去。」",
   "en": "Ruth the Moabitess said to Naomi, “Let me now go to the field, and glean among the ears of grain after him in whose sight I find favor.” She said to her, “Go, my daughter.”"
  },
  "3": {
   "zh": "路得就去了，來到田間，在收割的人身後拾取麥穗。她恰巧到了以利米勒本族的人波阿斯那塊田裡。",
   "en": "She went, and came and gleaned in the field after the reapers; and she happened to come to the portion of the field belonging to Boaz, who was of the family of Elimelech."
  },
  "4": {
   "zh": "波阿斯正從伯利恆來，對收割的人說：「願耶和華與你們同在！」他們回答說：「願耶和華賜福與你！」",
   "en": "Behold, Boaz came from Bethlehem, and said to the reapers, “May Yahweh be with you.” They answered him, “May Yahweh bless you.”"
  },
  "5": {
   "zh": "波阿斯問監管收割的僕人說：「那是誰家的女子？」",
   "en": "Then Boaz said to his servant who was set over the reapers, “Whose young lady is this?”"
  },
  "6": {
   "zh": "監管收割的僕人回答說：「是那摩押女子，跟隨拿俄米從摩押地回來的。",
   "en": "The servant who was set over the reapers answered, “It is the Moabite lady who came back with Naomi out of the country of Moab."
  },
  "7": {
   "zh": "她說：『請你容我跟著收割的人拾取打捆剩下的麥穗。』她從早晨直到如今，除了在屋子裡坐一會兒，常在這裡。」",
   "en": "She said, ‘Please let me glean and gather after the reapers among the sheaves.’ So she came, and has continued even from the morning until now, except that she rested a little in the house.”"
  },
  "8": {
   "zh": "波阿斯對路得說：「女兒啊，聽我說，不要往別人田裡拾取麥穗，也不要離開這裡，要常與我使女們在一處。",
   "en": "Then Boaz said to Ruth, “Listen, my daughter. Don’t go to glean in another field, and don’t go from here, but stay here close to my maidens."
  },
  "9": {
   "zh": "我的僕人在那塊田收割，你就跟著他們去。我已經吩咐僕人不可欺負你；你若渴了，就可以到器皿那裡喝僕人打來的水。」",
   "en": "Let your eyes be on the field that they reap, and go after them. Haven’t I commanded the young men not to touch you? When you are thirsty, go to the vessels, and drink from that which the young men have drawn.”"
  },
  "10": {
   "zh": "路得就俯伏在地叩拜，對他說：「我既是外邦人，怎麼蒙你的恩，這樣顧恤我呢？」",
   "en": "Then she fell on her face, and bowed herself to the ground, and said to him, “Why have I found favor in your sight, that you should take knowledge of me, since I am a foreigner?”"
  },
  "11": {
   "zh": "波阿斯回答說：「自從你丈夫死後，凡你向婆婆所行的，並你離開父母和本地，到素不認識的民中，這些事人全都告訴我了。",
   "en": "Boaz answered her, “I have been told all about what you have done for your mother-in-law since the death of your husband, and how you have left your father and your mother, and the land of your birth, and have come to a people that you didn’t know before."
  },
  "12": {
   "zh": "願耶和華照你所行的賞賜你。你來投靠耶和華─以色列神的翅膀下，願你滿得他的賞賜。」",
   "en": "May Yahweh repay your work, and a full reward be given to you from Yahweh, the God of Israel, under whose wings you have come to take refuge.”"
  },
  "13": {
   "zh": "路得說：「我主啊，願在你眼前蒙恩。我雖然不及你的一個使女，你還用慈愛的話安慰我的心。」",
   "en": "Then she said, “Let me find favor in your sight, my lord, because you have comforted me, and because you have spoken kindly to your servant, though I am not as one of your servants.”"
  },
  "14": {
   "zh": "到了吃飯的時候，波阿斯對路得說：「你到這裡來吃餅，將餅蘸在醋裡。」路得就在收割的人旁邊坐下；他們把烘了的穗子遞給她。她吃飽了，還有餘剩的。",
   "en": "At meal time Boaz said to her, “Come here, and eat some bread, and dip your morsel in the vinegar.” She sat beside the reapers, and they passed her parched grain, and she ate, and was satisfied, and left some of it."
  },
  "15": {
   "zh": "她起來又拾取麥穗，波阿斯吩咐僕人說：「她就是在捆中拾取麥穗，也可以容她，不可羞辱她；",
   "en": "When she had risen up to glean, Boaz commanded his young men, saying, “Let her glean even among the sheaves, and don’t reproach her."
  },
  "16": {
   "zh": "並要從捆裡抽出些來，留在地下任她拾取，不可叱嚇她。」",
   "en": "Also pull out some for her from the bundles, and leave it. Let her glean, and don’t rebuke her.”"
  },
  "17": {
   "zh": "這樣，路得在田間拾取麥穗，直到晚上，將所拾取的打了，約有一伊法大麥。",
   "en": "So she gleaned in the field until evening; and she beat out that which she had gleaned, and it was about an ephah of barley."
  },
  "18": {
   "zh": "她就把所拾取的帶進城去給婆婆看，又把她吃飽了所剩的給了婆婆。",
   "en": "She took it up, and went into the city. Then her mother-in-law saw what she had gleaned; and she brought out and gave to her that which she had left after she had enough."
  },
  "19": {
   "zh": "婆婆問她說：「你今日在哪裡拾取麥穗，在哪裡做工呢？願那顧恤你的得福。」路得就告訴婆婆說：「我今日在一個名叫波阿斯的人那裡做工。」",
   "en": "Her mother-in-law said to her, “Where have you gleaned today? Where have you worked? Blessed be he who noticed you.” She told her mother-in-law with whom she had worked, “The man’s name with whom I worked today is Boaz.”"
  },
  "20": {
   "zh": "拿俄米對兒婦說：「願那人蒙耶和華賜福，因為他不斷地恩待活人死人。」拿俄米又說：「那是我們本族的人，是一個至近的親屬。」",
   "en": "Naomi said to her daughter-in-law, “May he be blessed by Yahweh, who has not abandoned his kindness to the living and to the dead.” Naomi said to her, “The man is a close relative to us, one of our near kinsmen.”"
  },
  "21": {
   "zh": "摩押女子路得說：「他對我說：『你要緊隨我的僕人拾取麥穗，直等他們收完了我的莊稼。』」",
   "en": "Ruth the Moabitess said, “Yes, he said to me, ‘You shall stay close to my young men, until they have finished all my harvest.’”"
  },
  "22": {
   "zh": "拿俄米對兒婦路得說：「女兒啊，你跟著他的使女出去，不叫人遇見你在別人田間，這才為好。」",
   "en": "Naomi said to Ruth her daughter-in-law, “It is good, my daughter, that you go out with his maidens, and that they not meet you in any other field.”"
  },
  "23": {
   "zh": "於是路得與波阿斯的使女常在一處拾取麥穗，直到收完了大麥和小麥。路得仍與婆婆同住。",
   "en": "So she stayed close to the maidens of Boaz, to glean to the end of barley harvest and of wheat harvest; and she lived with her mother-in-law."
  }
 },
 "3": {
  "1": {
   "zh": "路得的婆婆拿俄米對她說：「女兒啊，我不當為你找個安身之處，使你享福嗎？",
   "en": "Naomi her mother-in-law said to her, “My daughter, shall I not seek rest for you, that it may be well with you?"
  },
  "2": {
   "zh": "你與波阿斯的使女常在一處，波阿斯不是我們的親族嗎？他今夜在場上簸大麥；",
   "en": "Now isn’t Boaz our kinsman, with whose maidens you were? Behold, he will be winnowing barley tonight on the threshing floor."
  },
  "3": {
   "zh": "你要沐浴抹膏，換上衣服，下到場上，卻不要使那人認出你來。你等他吃喝完了，",
   "en": "Therefore wash yourself, anoint yourself, get dressed, and go down to the threshing floor, but don’t make yourself known to the man until he has finished eating and drinking."
  },
  "4": {
   "zh": "到他睡的時候，你看準他睡的地方，就進去掀開他腳上的被，躺臥在那裡，他必告訴你所當做的事。」",
   "en": "It shall be, when he lies down, that you shall note the place where he is lying. Then you shall go in, uncover his feet, and lay down. Then he will tell you what to do.”"
  },
  "5": {
   "zh": "路得說：「凡你所吩咐的，我必遵行。」",
   "en": "She said to her, “All that you say, I will do.”"
  },
  "6": {
   "zh": "路得就下到場上，照她婆婆所吩咐她的而行。",
   "en": "She went down to the threshing floor, and did everything that her mother-in-law told her."
  },
  "7": {
   "zh": "波阿斯吃喝完了，心裡歡暢，就去睡在麥堆旁邊。路得便悄悄地來掀開他腳上的被，躺臥在那裡。",
   "en": "When Boaz had eaten and drunk, and his heart was merry, he went to lie down at the end of the heap of grain. She came softly, uncovered his feet, and laid down."
  },
  "8": {
   "zh": "到了夜半，那人忽然驚醒，翻過身來，不料有女子躺在他的腳下。",
   "en": "At midnight, the man was startled and turned himself; and behold, a woman lay at his feet."
  },
  "9": {
   "zh": "他就說：「你是誰？」回答說：「我是你的婢女路得。求你用你的衣襟遮蓋我，因為你是我一個至近的親屬。」",
   "en": "He said, “Who are you?” She answered, “I am Ruth your servant. Therefore spread the corner of your garment over your servant; for you are a near kinsman.”"
  },
  "10": {
   "zh": "波阿斯說：「女兒啊，願你蒙耶和華賜福。你末後的恩比先前更大；因為少年人無論貧富，你都沒有跟從。",
   "en": "He said, “You are blessed by Yahweh, my daughter. You have shown more kindness in the latter end than at the beginning, because you didn’t follow young men, whether poor or rich."
  },
  "11": {
   "zh": "女兒啊，現在不要懼怕，凡你所說的，我必照著行；我本城的人都知道你是個賢德的女子。",
   "en": "Now, my daughter, don’t be afraid. I will do to you all that you say; for all the city of my people knows that you are a worthy woman."
  },
  "12": {
   "zh": "我實在是你一個至近的親屬，只是還有一個人比我更近。",
   "en": "Now it is true that I am a near kinsman. However, there is a kinsman nearer than I."
  },
  "13": {
   "zh": "你今夜在這裡住宿，明早他若肯為你盡親屬的本分，就由他吧！倘若不肯，我指著永生的耶和華起誓，我必為你盡了本分，你只管躺到天亮。」",
   "en": "Stay this night, and in the morning, if he will perform for you the part of a kinsman, good. Let him do the kinsman’s duty. But if he will not do the duty of a kinsman for you, then I will do the duty of a kinsman for you, as Yahweh lives. Lie down until the morning.”"
  },
  "14": {
   "zh": "路得便在他腳下躺到天快亮，人彼此不能辨認的時候就起來了。波阿斯說：「不可使人知道有女子到場上來」；",
   "en": "She lay at his feet until the morning, then she rose up before one could discern another. For he said, “Let it not be known that the woman came to the threshing floor.”"
  },
  "15": {
   "zh": "又對路得說：「打開你所披的外衣。」她打開了，波阿斯就撮了六簸箕大麥，幫她扛在肩上，她便進城去了。",
   "en": "He said, “Bring the mantle that is on you, and hold it.” She held it; and he measured six measures of barley, and laid it on her; then he went into the city."
  },
  "16": {
   "zh": "路得回到婆婆那裡，婆婆說：「女兒啊，怎麼樣了？」路得就將那人向她所行的述說了一遍，",
   "en": "When she came to her mother-in-law, she said, “How did it go, my daughter?” She told her all that the man had done for her."
  },
  "17": {
   "zh": "又說：「那人給了我六簸箕大麥，對我說：『你不可空手回去見你的婆婆。』」",
   "en": "She said, “He gave me these six measures of barley; for he said, ‘Don’t go empty to your mother-in-law.’”"
  },
  "18": {
   "zh": "婆婆說：「女兒啊，你只管安坐等候，看這事怎樣成就，因為那人今日不辦成這事必不休息。」",
   "en": "Then she said, “Wait, my daughter, until you know what will happen; for the man will not rest until he has settled this today.”"
  }
 },
 "4": {
  "1": {
   "zh": "波阿斯到了城門，坐在那裡，恰巧波阿斯所說的那至近的親屬經過。波阿斯說：「某人哪，你來坐在這裡。」他就來坐下。",
   "en": "Now Boaz went up to the gate, and sat down there. Behold, the near kinsman of whom Boaz spoke came by. He said to him, “Come over here, friend, and sit down!” He came over, and sat down."
  },
  "2": {
   "zh": "波阿斯又從本城的長老中揀選了十人，對他們說：「請你們坐在這裡。」他們就都坐下。",
   "en": "He took ten men of the elders of the city, and said, “Sit down here,” and they sat down."
  },
  "3": {
   "zh": "波阿斯對那至近的親屬說：「從摩押地回來的拿俄米，現在要賣我們族兄以利米勒的那塊地；",
   "en": "He said to the near kinsman, “Naomi, who has come back out of the country of Moab, is selling the parcel of land, which was our brother Elimelech’s."
  },
  "4": {
   "zh": "我想當贖那塊地的是你，其次是我，以外再沒有別人了。你可以在這裡的人面前和我本國的長老面前說明，你若肯贖就贖，若不肯贖就告訴我。」那人回答說：「我肯贖。」",
   "en": "I thought I should tell you, saying, ‘Buy it before those who sit here, and before the elders of my people.’ If you will redeem it, redeem it; but if you will not redeem it, then tell me, that I may know. For there is no one to redeem it besides you; and I am after you.” He said, “I will redeem it.”"
  },
  "5": {
   "zh": "波阿斯說：「你從拿俄米手中買這地的時候，也當娶（原文是買；十節同）死人的妻摩押女子路得，使死人在產業上存留他的名。」",
   "en": "Then Boaz said, “On the day you buy the field from the hand of Naomi, you must buy it also from Ruth the Moabitess, the wife of the dead, to raise up the name of the dead on his inheritance.”"
  },
  "6": {
   "zh": "那人說：「這樣我就不能贖了，恐怕於我的產業有礙。你可以贖我所當贖的，我不能贖了。」",
   "en": "The near kinsman said, “I can’t redeem it for myself, lest I endanger my own inheritance. Take my right of redemption for yourself; for I can’t redeem it.”"
  },
  "7": {
   "zh": "從前，在以色列中要定奪甚麼事，或贖回，或交易，這人就脫鞋給那人。以色列人都以此為證據。",
   "en": "Now this was the custom in former time in Israel concerning redeeming and concerning exchanging, to confirm all things: a man took off his shoe, and gave it to his neighbor; and this was the way of formalizing transactions in Israel."
  },
  "8": {
   "zh": "那人對波阿斯說：「你自己買吧！」於是將鞋脫下來了。",
   "en": "So the near kinsman said to Boaz, “Buy it for yourself,” then he took off his shoe."
  },
  "9": {
   "zh": "波阿斯對長老和眾民說：「你們今日作見證，凡屬以利米勒和基連、瑪倫的，我都從拿俄米手中置買了；",
   "en": "Boaz said to the elders, and to all the people, “You are witnesses today, that I have bought all that was Elimelech’s, and all that was Chilion’s and Mahlon’s, from the hand of Naomi."
  },
  "10": {
   "zh": "又娶了瑪倫的妻摩押女子路得為妻，好在死人的產業上存留他的名，免得他的名在本族本鄉滅沒。你們今日可以作見證。」",
   "en": "Moreover Ruth the Moabitess, the wife of Mahlon, I have purchased to be my wife, to raise up the name of the dead on his inheritance, that the name of the dead may not be cut off from among his brothers, and from the gate of his place. You are witnesses today.”"
  },
  "11": {
   "zh": "在城門坐著的眾民和長老都說：「我們作見證。願耶和華使進你家的這女子，像建立以色列家的拉結、利亞二人一樣。又願你在以法他得亨通，在伯利恆得名聲。",
   "en": "All the people who were in the gate, and the elders, said, “We are witnesses. May Yahweh make the woman who has come into your house like Rachel and like Leah, which both built the house of Israel; and treat you worthily in Ephrathah, and be famous in Bethlehem."
  },
  "12": {
   "zh": "願耶和華從這少年女子賜你後裔，使你的家像他瑪從猶大所生法勒斯的家一般。」",
   "en": "Let your house be like the house of Perez, whom Tamar bore to Judah, of the offspring which Yahweh will give you by this young woman.”"
  },
  "13": {
   "zh": "於是，波阿斯娶了路得為妻，與她同房。耶和華使她懷孕生了一個兒子。",
   "en": "So Boaz took Ruth, and she became his wife; and he went in to her, and Yahweh enabled her to conceive, and she bore a son."
  },
  "14": {
   "zh": "婦人們對拿俄米說：「耶和華是應當稱頌的！因為今日沒有撇下你，使你無至近的親屬。願這孩子在以色列中得名聲。",
   "en": "The women said to Naomi, “Blessed be Yahweh, who has not left you today without a near kinsman. Let his name be famous in Israel."
  },
  "15": {
   "zh": "他必提起你的精神，奉養你的老，因為是愛慕你的那兒婦所生的。有這兒婦比有七個兒子還好！」",
   "en": "He shall be to you a restorer of life, and sustain you in your old age, for your daughter-in-law, who loves you, who is better to you than seven sons, has given birth to him.”"
  },
  "16": {
   "zh": "拿俄米就把孩子抱在懷中，作他的養母。",
   "en": "Naomi took the child, and laid him in her bosom, and became nurse to it."
  },
  "17": {
   "zh": "鄰舍的婦人說：「拿俄米得孩子了！」就給孩子起名叫俄備得。這俄備得是耶西的父，耶西是大衛的父。",
   "en": "The women, her neighbors, gave him a name, saying, “A son is born to Naomi”. They named him Obed. He is the father of Jesse, the father of David."
  },
  "18": {
   "zh": "法勒斯的後代記在下面：法勒斯生希斯崙；",
   "en": "Now this is the history of the generations of Perez: Perez became the father of Hezron,"
  },
  "19": {
   "zh": "希斯崙生蘭；蘭生亞米拿達；",
   "en": "and Hezron became the father of Ram, and Ram became the father of Amminadab,"
  },
  "20": {
   "zh": "亞米拿達生拿順；拿順生撒門；",
   "en": "and Amminadab became the father of Nahshon, and Nahshon became the father of Salmon,"
  },
  "21": {
   "zh": "撒門生波阿斯；波阿斯生俄備得；",
   "en": "and Salmon became the father of Boaz, and Boaz became the father of Obed,"
  },
  "22": {
   "zh": "俄備得生耶西；耶西生大衛。",
   "en": "and Obed became the father of Jesse, and Jesse became the father of David."
  }
 }
};
